sys_ui_action.script:
// Changes the status of the HSBC email log to sent-ready once the agent has reviewed the content of the email
var emailLog = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_log');
emailLog.addQuery('trade_case_task_number', current.sys_id);
emailLog.query();
if (emailLog.next()) {
    //var getAutomationGroupSysID = gs.getProperty('HSBC_SN Automation_Group'); // get the sys id of the SN Automation group
    var getAutomationTaskID = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
	//MSSRBXCE-307-401 include the TUNM email automation task 'Prepare TUNM pre-populated Client Follow Up Email' in the filter
    getAutomationTaskID.addEncodedQuery('short_description=Prepare TUNM pre-populated Client Follow Up Email^ORshort_description=Trigger Email Communications Handler for follow up email to Client^ORshort_description=Send email to CTM^ORshort_description=Trigger Email Handler to proactively contact Client^state=1^parent=' + current.parent); // Look for the SN automation task and assign the email log to task as all the processes run based on the SN Automation task
    getAutomationTaskID.orderByDesc();
    getAutomationTaskID.query();
    if (getAutomationTaskID.next()) {
        emailLog.trade_case_task_number = getAutomationTaskID.sys_id; // update the reference from the current task to the SN automation task ID
		emailLog.api_response_from_qtrack = 'Sent-Ready'; // Set the state of the HSBC email to Send ready so the email can then be triggered.
    }
	var getAutomationTaskID_two = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
	//MSSRBXCE-307-401 include the TUNM email review task 'MOCS to review & enrich a prepopulated email template to the Client (including the Client Trader Name)' in the filter
	getAutomationTaskID_two.addEncodedQuery('short_description=Review and provide any further details of follow-up investigation^ORshort_description=MOCS to review & enrich a prepopulated email template to the Client (including the Client Trader Name)^parent=' + current.parent);
	getAutomationTaskID_two.query();
	if (getAutomationTaskID_two.next()) {
	emailLog.api_response_from_qtrack = 'Sent-Ready';
    emailLog.update();
	}
}

//MSSRBXCE-307-401 add the if condition here, as different outcome required for the TUNM email review task 'MOCS to review & enrich a prepopulated email template to the Client (including the Client Trader Name)'
if (current.short_description == 'MOCS to review & enrich a prepopulated email template to the Client (including the Client Trader Name)')
    current.outcome = 'Email ready to send';
else
    current.outcome = 'Email Client';
current.state =  '3';
current.update();


//MSSRBXCE-307-401 Clean up swb_widget_outcome and email_handler_outcome from all trade cases which aggregated in this email
if (current.short_description == 'MOCS to review & enrich a prepopulated email template to the Client (including the Client Trader Name)') {
    var childEmailQueue = new GlideRecord('x_hsb11_hsbcmss_eh_aggregated_trade_email_queue');
    childEmailQueue.addQuery("trade_case_task", getAutomationTaskID.sys_id);
    childEmailQueue.query();
    if (childEmailQueue.next()) {
        var childEmailQueue_two = new GlideRecord('x_hsb11_hsbcmss_eh_aggregated_trade_email_queue');
        childEmailQueue_two.addQuery("parent", childEmailQueue.parent);
        childEmailQueue_two.query(); //get all child records which covered in the same parent aggregated email queue
        while (childEmailQueue_two.next()) {
            var tradeCase = new GlideRecord('x_hsb11_hsbc_mss_t_trade_case');
            tradeCase.addQuery("sys_id", childEmailQueue_two.trade_case);
			tradeCase.addQuery("state", "!=", 7);
            tradeCase.query();
            if (tradeCase.next()) {
                tradeCase.swb_widget_outcome = '';
                tradeCase.email_handler_outcome = '';
                tradeCase.update();
            }
        }
    }
}
